from itertools import combinations

# Edges in lexicographic order
edges = [(i, j) for i in range(5) for j in range(i+1, 5)]
edge_to_idx = {e: i for i, e in enumerate(edges)}

# Triangles
triangles = list(combinations(range(5), 3))

# Constraints: for each triangle, not all edges are 0, and not all edges are 1
def check(coloring):
    for tri in triangles:
        idxs = [edge_to_idx[(tri[0], tri[1])], edge_to_idx[(tri[0], tri[2])], edge_to_idx[(tri[1], tri[2])]]
        vals = [coloring[i] for i in idxs]
        if all(v == 0 for v in vals) or all(v == 1 for v in vals):
            return False
    return True

# Fixed assignments
fixed = {3: 1, 9: 0}

# Try all 2^8 possibilities for the remaining 8 edges
import itertools
for bits in itertools.product([0, 1], repeat=8):
    coloring = [0] * 10
    coloring[3] = 1
    coloring[9] = 0
    idx = 0
    for i in range(10):
        if i not in fixed:
            coloring[i] = bits[idx]
            idx += 1
    if check(coloring):
        print("Solution found:", coloring)
        break
else:
    print("UNSATISFIABLE")
